fn read_class37(path:&str)->Vec<Series>{let text=fs::read_to_string(path).unwrap();let mut out=vec![];for line in text.lines(){let p:Vec<_>=line.split_whitespace().collect();assert_eq!(p.len(),155);assert_eq!(p[0].parse::<usize>().unwrap(),out.len()+1);let mut v=[0;N];for i in 0..N{v[i]=p[i+1].parse().unwrap();assert!(v[i]<32);}out.push(v);}assert_eq!(out.len(),196);out}
fn main(){let args:Vec<String>=env::args().collect();assert_eq!(args.len(),5);let spaces=read(&args[1]);let v=&spaces[2];let base=&spaces[0];let zero=&spaces[1];let e=read_class37(&args[2]);let f=read_class37(&args[3]);let ambient=series_basis36(v);for c in e.iter().chain(f.iter()){assert_eq!(residual36(pack(c),&ambient),[0;W]);}series_basis36(&e);series_basis36(&f);let mut table=[[0u8;32];32];for a in 0..32{for b in 0..32{table[a][b]=field(a as u8,b as u8);assert_eq!(table[a][b],field_independent(a as u8,b as u8));}}
 fs::create_dir(&args[4]).unwrap();let mut out=BufWriter::new(fs::File::create(format!("{}/torsion-certificates.txt",args[4])).unwrap());
 let e2=add37("first-2",v,base,&e,&e,&table,&mut out);let e4=add37("first-4",v,base,&e2,&e2,&table,&mut out);let e8=add37("first-8",v,base,&e4,&e4,&table,&mut out);let e10=add37("first-10",v,base,&e8,&e2,&table,&mut out);let e11=add37("first-11",v,base,&e10,&e,&table,&mut out);let e5=add37("first-5",v,base,&e4,&e,&table,&mut out);
 let eleven_zero=same37("first-11-versus-zero",v,&e11,zero,&table,&mut out);let five_zero=same37("first-5-versus-zero",v,&e5,zero,&table,&mut out);assert!(!(eleven_zero&&five_zero),"nonzero source cannot be killed by coprime5and11");
 let f2=add37("second-2",v,base,&f,&f,&table,&mut out);let f3=add37("second-3",v,base,&f2,&f,&table,&mut out);let f4=add37("second-4",v,base,&f2,&f2,&table,&mut out);let f5=add37("second-5",v,base,&f4,&f,&table,&mut out);let f6=add37("second-6",v,base,&f3,&f3,&table,&mut out);let f11=add37("second-11",v,base,&f6,&f5,&table,&mut out);
 assert!(same37("two-eleven-expressions",v,&e11,&f11,&table,&mut out));let second_eleven_zero=same37("second-11-versus-zero",v,&f11,zero,&table,&mut out);assert_eq!(eleven_zero,second_eleven_zero);
 save37(&args[4],"eleven-first",&e11);save37(&args[4],"eleven-second",&f11);save37(&args[4],"five-first",&e5);out.flush().unwrap();fs::write(format!("{}/torsion-result.txt",args[4]),format!("eleven_kills={eleven_zero}\nfive_kills={five_zero}\nindependent_eleven_expressions_equal=true\n")).unwrap();println!("TORSION37_RESULT source_nonprincipal=true eleven_kills={eleven_zero} five_kills={five_zero} independent_eleven_expressions_equal=true all_generator_memberships=checked independent_products=all target_factor_evaluated=false");println!("TORSION37_ALL_CHECKS_PASS");}
